int64_t Civil(int y,unsigned m,unsigned d){y-=m<=2;int era=(y>=0?y:y-399)/400;unsigned yoe=y-era*400,doy=(153*(m+(m>2?-3:9))+2)/5+d-1,doe=yoe*365+yoe/4-yoe/100+doy;return(int64_t)era*146097+doe-719468;}
int Sunday(int year,int month,int nth){int weekday=(Civil(year,month,1)+4)%7;int day=1+(7-weekday)%7+7*(nth-1);if(nth==5){int days=month==2?28:month==4||month==6||month==9||month==11?30:31;while(day>days)day-=7;}return day;}
int Offset(const City&c,time_t now){if(!c.dst)return c.offset;tm u{};gmtime_r(&now,&u);int y=u.tm_year+1900;auto stamp=[&](int month,int day,int hour){return Civil(y,month,day)*86400+hour*3600;};bool dst=false;
 if(c.dst==1)dst=now>=stamp(3,Sunday(y,3,5),1)&&now<stamp(10,Sunday(y,10,5),1);
 else if(c.dst==2)dst=now>=stamp(3,Sunday(y,3,2),2)-c.offset*60&&now<stamp(11,Sunday(y,11,1),2)-(c.offset+60)*60;
 else {time_t local=now+c.offset*60;tm t{};gmtime_r(&local,&t);dst=t.tm_mon<3||t.tm_mon>9||(t.tm_mon==3&&(t.tm_mday<Sunday(y,4,1)||(t.tm_mday==Sunday(y,4,1)&&t.tm_hour<2)))||(t.tm_mon==9&&(t.tm_mday>Sunday(y,10,1)||(t.tm_mday==Sunday(y,10,1)&&t.tm_hour>=2)));}
 return c.offset+(dst?60:0);}
// This firmware stores CLOCK_REALTIME as Beijing wall time (LOCALTIME off).
// Use the same source as the status bar, applying only the city difference.
time_t UtcTime(time_t system){
#ifndef CONFIG_LIBC_LOCALTIME
 return system-8*3600;
#else
 return system;
#endif
}
bool CityTime(const City&city,time_t system,tm&out){if(!metalio_board_clock_ready()||system<=1700000000)return false;if(city.offset==480&&!city.dst)return localtime_r(&system,&out)!=nullptr;time_t utc=UtcTime(system),shifted=utc+Offset(city,utc)*60;return gmtime_r(&shifted,&out)!=nullptr;}
