void ClockScreen::InitGlobal(){ClockService::Init();if(global_timer)return;global_timer=lv_timer_create([](lv_timer_t*){auto s=ClockService::GetAlert();if(!s.alert){if(alert){lv_obj_delete(alert);alert=nullptr;}alert_id=0;return;}IdlePower_NotifyActivity();if(alert&&alert_id==s.alert)return;if(alert)lv_obj_delete(alert);alert_id=s.alert;if(StandbyScreen::IsVisible())StandbyScreen::ReturnHome();HiInputMethod_Suspend();alert=Box(lv_layer_sys(),0,0,720,720,0xF7F9F6);lv_obj_move_foreground(alert);Label(alert,s.alert_label.c_str(),60,185,600,true);Label(alert,"时间到了",60,250,600,true,0xB16A53);Button(alert,"稍后 5 分钟",100,410,230,80,[](lv_event_t*){ClockService::Dismiss(true);if(alert)lv_obj_add_flag(alert,LV_OBJ_FLAG_HIDDEN);});Button(alert,"停止",390,410,230,80,[](lv_event_t*){ClockService::Dismiss(false);if(alert)lv_obj_add_flag(alert,LV_OBJ_FLAG_HIDDEN);});},200,nullptr);}
